// VerifyDataColumnSidecar — called BEFORE KZG verification:
func VerifyDataColumnSidecar(sidecar blocks.RODataColumn) error {
	numberOfColumns := params.BeaconConfig().NumberOfColumns
	if sidecar.Index >= numberOfColumns { return ErrIndexTooLarge } // bounds check
	if len(sidecar.KzgCommitments) == 0 { return ErrNoKzgCommitments }
	if len(sidecar.Column) != len(sidecar.KzgCommitments) || len(sidecar.Column) != len(sidecar.KzgProofs) { return ErrMismatchLength }
	return nil
}

